#!/usr/bin/env python3
"""Source-specific reference names and explicit remaining audit scopes."""
import json,time
from pathlib import Path
import yaml
ROOT=Path(__file__).resolve().parents[1];folder=ROOT/'catalog/settings/backlog';folder.mkdir(parents=True,exist_ok=True)
def save(path,data):path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');path.with_suffix('.yaml').write_text(yaml.safe_dump(data,allow_unicode=True,sort_keys=False))
entities=[{'id':kind+':'+key,'kind':kind,'label':label,'aliases':aliases,'parent_ids':parents,'note':'Source-specific research facet; no original-book completeness or implemented game effects asserted.'} for kind,key,label,aliases,parents in [
 ('topic','backlog-reference','Campaign and game source references',[],[]),('game','conan-exiles','Conan Exiles',[],[]),('setting','hyborian-age','Hyborian Age',['Conan setting'],[]),('game','planescape-torment','Planescape: Torment',['PST'],[]),('publication','curse-of-strahd','Curse of Strahd',['CoS'],[]),('publication','tomb-annihilation','Tomb of Annihilation',['ToA'],[]),('publication','rime-frostmaiden','Icewind Dale: Rime of the Frostmaiden',['Rime of the Frostmaiden','Frostmaiden','Frostmaidens'],[]),('region','chult','Chult',[],['setting:forgotten-realms']),('region','icewind-dale','Icewind Dale',[],['setting:forgotten-realms'])]]
refs=[{'id':'cos','url':'https://cori-spells.github.io/wikidot/dnd5e.wikidot.com/wondrous-items_cos.html','source_kind':'secondary-name-index','note':'Names/types only. Tome separately attested by the campaign item appendix index.'},{'id':'toa','url':'https://dnd5e.wikidot.com/wondrous-items:toa','source_kind':'secondary-name-index'},{'id':'rime','url':'https://dnd5e.wikidot.com/wondrous-items:id:rf','source_kind':'secondary-name-index'},{'id':'conan','url':'https://conanexiles.th.gl/db/inventory','source_kind':'fan-public-inventory-index'},{'id':'d4','url':'https://diablo4.th.gl/db/uniques','source_kind':'fan-public-unique-index'},{'id':'pst','url':'https://shrines.rpgclassics.com/pc/planescape/items.shtml','source_kind':'fan-inventory-tables'}]
pack={'schema_version':1,'id':'backlog-reference-registry','label':'Backlog reference registry (no draft records)','theme':'source-research','topic_entity_id':'topic:backlog-reference','sources':refs,'entities':entities,'items':[],'coverage':'Taxonomy and audit queue only; actual reference records belong to their separately counted source indexes.'};save(folder/'research-pack.json',pack)
setting=ROOT/'catalog/raw/setting-reference-indexes';setting.mkdir(parents=True,exist_ok=True)
for key,label,entity,world,url,rows in [
 ('curse-of-strahd-reference','Curse of Strahd','curse-of-strahd','ravenloft',refs[0]['url'],[('Blood Spear','weapon'),('Gulthias Staff','staff'),("Saint Markovia's Thighbone",'weapon'),('Holy Symbol of Ravenkind','wondrous-item'),('Icon of Ravenloft','wondrous-item'),('Sunsword','weapon'),('Tome of Strahd','book')]),
 ('tomb-annihilation-reference','Tomb of Annihilation','tomb-annihilation','forgotten-realms',refs[1]['url'],[('Mask of the Beast','wondrous-item'),('Ghost Lantern','wondrous-item'),('Scorpion Armor','armor'),('Amulet of the Black Skull','wondrous-item'),('Bookmark','weapon'),('Ring of Winter','ring'),('Staff of the Forgotten One','staff')]),
 ('rime-frostmaiden-reference','Icewind Dale: Rime of the Frostmaiden','rime-frostmaiden','forgotten-realms',refs[2]['url'],[('Lantern of Tracking','wondrous-item'),('Thermal Cube','wondrous-item'),('Psi Crystal','wondrous-item'),('Cauldron of Plenty','wondrous-item'),("Hook of Fisher's Delight",'wondrous-item'),('Professor Orb','wondrous-item'),('Abracadabrus','wondrous-item'),('Scroll of Tarrasque Summoning','scroll'),('Scroll of the Comet','scroll'),('Ythryn Mythallar','wondrous-item')])]:
 records=[]
 for name,typ in rows:
  r={'name':name,'source_type':typ,'url':url,'evidence_kind':'secondary-book-name-index','original_book_verified':False,'ninja_relevance':'backlog'}
  if name=='Tome of Strahd':r['url']='https://www.thedarkelf007.com/about/library/dnd/dnd-5e-wiz-adv-cos.html'
  if name=='Ythryn Mythallar':r.update(record_kind='construction-component',placement_status='fixed-installation-reference-not-portable-equipment')
  records.append(r)
 data={'source_id':key,'label':label,'entity_id':'publication:'+entity,'setting_id':world,'ruleset':'dnd-2014','source_url':url,'retrieved_at':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'coverage':'Selected distinctive item names from a secondary index. Not every ordinary item, chapter treasure, special material, story prop or artifact in the book. No source rules or prose reproduced. 2024 compatibility audit pending.','records':records}
 (setting/(key+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
# Named skyships are research leads, separate from portable item and construction counts.
skyships=['The Princess Ark',"Azlum Swith’s Geodome Airship","Oberack’s Dragon Prow Longship",'Elven Swan Ship','Flying Barge of Sayr Ulan','The Enchanting','Oostdok Airship','Heldannic Warbird, Light','Heldannic Warbird, Heavy','Alphatian Man-o-war','Alphatian Yacht','Voidship, Lightrider','Voidship, Windrider','Pyrithian Pirateship']
save(ROOT/'catalog/settings/mystara-frontiers/skyship-leads.json',{'source_url':'https://www.pandius.com/knwnskys.html','status':'fan-index-claims-Champions-source-original-book-not-verified','leads':[{'name':n,'counted_as_catalog_item':False,'audit_status':'original-entry-and-2024-vehicle-rules-pending'} for n in skyships]})
queue={'workstreams':[{'id':key,'label':label,'status':status,'original_book_item_audit_complete':False} for key,label,status in [('planescape','Planescape / Planescape: Torment','selected-game-inventory-references-imported-tabletop-books-pending'),('curse-of-strahd','Curse of Strahd','seven-distinctive-name-references-original-book-audit-pending'),('tomb-annihilation','Tomb of Annihilation','seven-distinctive-name-references-chapter-treasure-and-equipment-pending'),('rime-frostmaiden','Icewind Dale: Rime of the Frostmaiden','ten-distinctive-name-references-chapter-items-spellbooks-materials-pending'),('diablo-4','Diablo IV','selected-unique-name-index-imported-2024-adaptation-pending'),('conan-exiles','Conan Exiles construction and equipment','public-inventory-reference-snapshot-pet-tokens-excluded')]],'next_audit_scopes':{'tomb-annihilation':['Chultan adventuring gear','story treasures and artifacts','dinosaur transport','ordinary equipment appearances','chapter-specific modified items'],'rime-frostmaiden':['cold-weather equipment and transport','Codicil of White and spellbooks','chardalyn materials and corrupted variants','Summer Star and other chapter objects','chapter-specific modified items'],'curse-of-strahd':['ordinary treasure appearances','chapter-specific modified items','story objects beyond magic appendix'],'planescape':['tabletop boxed-set item sources','faction-specific equipment','portal keys and planar materials']},'count_policy':'Names are references. Do not count NPCs, spells, pet tokens, arbitrary affix combinations or named ship leads as converted inventory.'}
save(folder/'research-queue.json',queue)
print('Book reference indexes: 24 selected names; skyship leads: 14 (uncounted)')
